```yaml
name: Weekly Repo Status

on:
  schedule:
    # Runs every Sunday at 00:00 UTC
    - cron: '0 0 * * 0'

permissions:
  contents: read
  issues: write

jobs:
  generate-status:
    runs-on: ubuntu-latest
    steps:
      - name: Checkout repository
        uses: actions/checkout@v4

      - name: Generate and publish weekly status
        uses: actions/github-script@v6
        with:
          script: |
            const core = require('@actions/core');
            const github = require('@actions/github');
            const context = github.context;

            // Helper to format dates for the GitHub API
            const isoDate = d => d.toISOString().split('T')[0];

            // Calculate week start (Monday) and end (next Monday)
            const now = new Date();
            const day = now.getUTCDay(); // 0=Sunday, 1=Monday, ...
            const mondayOffset = (day + 6) % 7; // days since Monday
            const weekStart = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate() - mondayOffset));
            const weekEnd = new Date(weekStart);
            weekEnd.setUTCDate(weekStart.getUTCDate() + 7);

            const formatDate = d => d.toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
            const dateRange = `${formatDate(weekStart)}–${formatDate(weekEnd)}, ${weekStart.getFullYear()}`;

            // Fetch merged PRs in the week
            const mergedPRs = await github.paginate('GET /search/issues', {
              q: `repo:${context.repo.owner}/${context.repo.repo} is:pr is:merged merged:${isoDate(weekStart)}..${isoDate(weekEnd)}`,
              per_page: 100
            });

            // Fetch issues created in the week
            const openedIssues = await github.paginate('GET /search/issues', {
              q: `repo:${context.repo.owner}/${context.repo.repo} is:issue created:${isoDate(weekStart)}..${isoDate(weekEnd)}`,
              per_page: 100
            });

            // Fetch issues closed in the week
            const closedIssues = await github.paginate('GET /search/issues', {
              q: `repo:${context.repo.owner}/${context.repo.repo} is:issue is:closed closed:${isoDate(weekStart)}..${isoDate(weekEnd)}`,
              per_page: 100
            });

            const mergedCount = mergedPRs.length;
            const openedCount = openedIssues.length;
            const closedCount = closedIssues.length;

            // Build markdown report
            let report = `## 📊 Weekly Repo Status — ${dateRange}\n\n`;
            report += `- **${mergedCount} merged PRs**\n`;
            report += `- **${openedCount} issues opened**\n`;
            report += `- **${closedCount} issues closed**\n\n`;
            report += `### Issues This Week\n\n`;
            report += `#### Issues Opened: ${openedCount}\n\n`;
            report += `| Skill | Count | Issues |\n`;
            report += `|-------|-------|--------|\n`;
            report += `| *Not aggregated* | *${openedCount}* | *See issue list* |\n\n`;
            report += `#### Issues Closed: ${closedCount}\n\n`;
            report += `| Skill | Issues |\n`;
            report += `|-------|--------|\n`;
            report += `| *Not aggregated* | *${closedCount}* |\n`;

            const title = `Weekly Repo Status — ${dateRange}`;

            // Find existing weekly issue
            const existing = await github.paginate('GET /search/issues', {
              q: `repo:${context.repo.owner}/${context.repo.repo} is:issue label:weekly in:title "Weekly Repo Status"`,
              per_page: 100
            });

            const issue = existing.find(i => i.title === title);

            if (issue) {
              // Update existing issue
              await github.rest.issues.update({
                owner: context.repo.owner,
                repo: context.repo.repo,
                issue_number: issue.number,
                title,
                body: report,
                labels: ['status', 'weekly']
              });
              core.info(`Updated issue #${issue.number}`);
            } else {
              // Create new issue
              await github.rest.issues.create({
                owner: context.repo.owner,
                repo: context.repo.repo,
                title,
                body: report,
                labels: ['status', 'weekly']
              });
              core.info(`Created new weekly status issue`);
            }
